/**
 * Development-only Pagefind index.
 *
 * Pagefind normally indexes the built HTML, which means `astro dev` has no index at all. This
 * module builds a small index straight from the repository docs so search also works locally.
 * Production builds keep using Pagefind's HTML index generated by Starlight.
 */
import { existsSync, mkdirSync, readFileSync, renameSync, rmSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import * as pagefind from 'pagefind';
import { docItems, routeSegments, translationSource } from './docs-nav.mjs';
import { extractDescription, extractTitle, stripLanguageSwitcher } from './sync-docs.mjs';

const scriptDir = dirname(fileURLToPath(import.meta.url));
export const siteRoot = resolve(scriptDir, '..');
export const repoRoot = resolve(siteRoot, '../..');

/** Strip Markdown syntax while keeping the prose and code searchable. */
export function markdownToText(markdown) {
  const output = [];
  let inFence = false;
  for (const line of markdown.split('\n')) {
    const trimmed = line.trim();
    if (/^(```|~~~)/.test(trimmed)) {
      inFence = !inFence;
      continue;
    }
    if (inFence) {
      if (trimmed) output.push(trimmed);
      continue;
    }
    if (!trimmed || trimmed.startsWith('<!--')) continue;

    const text = line
      .replace(/!\[([^\]]*)\]\([^)]*\)/g, '$1')
      .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')
      .replace(/<[^>]+>/g, ' ')
      .replace(/`([^`]+)`/g, '$1')
      .replace(/\*\*([^*]+)\*\*/g, '$1')
      .replace(/\*([^*]+)\*/g, '$1')
      .replace(/^#{1,6}\s+/, '')
      .replace(/^>\s?/, '')
      .replace(/^\s*(?:[-*+]|\d+\.)\s+/, '')
      .replace(/\|/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
    if (text) output.push(text);
  }
  return output.join('\n');
}

function readDoc(source) {
  const path = join(repoRoot, source);
  return existsSync(path) ? readFileSync(path, 'utf8').replace(/\r\n/g, '\n') : null;
}

function frontmatterValue(markdown, key) {
  const match = markdown.match(new RegExp(`^${key}:\\s*(.+)$`, 'm'));
  return match?.[1].trim().replace(/^["']|["']$/g, '') ?? '';
}

/** Landing-page title, description and hero tagline, mirroring what Pagefind indexes in a build. */
function landingRecord(locale) {
  const source = locale === 'root' ? 'index.mdx' : 'zh-cn/index.mdx';
  const path = join(siteRoot, 'src/content/docs', source);
  if (!existsSync(path)) return null;

  const markdown = readFileSync(path, 'utf8').replace(/\r\n/g, '\n');
  const title = frontmatterValue(markdown, 'title');
  const description = frontmatterValue(markdown, 'description');
  const tagline = frontmatterValue(markdown, 'tagline');
  return {
    url: locale === 'root' ? '/' : '/zh-cn/',
    language: locale === 'root' ? 'en' : 'zh-cn',
    meta: { title, description },
    content: [title, description, tagline].filter(Boolean).join('\n\n'),
  };
}

/**
 * One Pagefind record per site page and locale. URLs stay relative to the site base so Pagefind's
 * `baseUrl` option (`/lattice/` locally, `/` in production) can prefix them.
 */
export function collectDevSearchRecords() {
  const records = [];
  for (const locale of ['root', 'zh-cn']) {
    const language = locale === 'root' ? 'en' : 'zh-cn';

    const landing = landingRecord(locale);
    if (landing) records.push(landing);

    for (const item of docItems) {
      const source = locale === 'root' ? item.source : translationSource(item.source);
      const markdown = readDoc(source);
      if (!markdown) continue;

      const lines = stripLanguageSwitcher(markdown.split('\n'));
      const titleInfo = extractTitle(lines);
      const title = titleInfo?.title ?? item.label;
      const description = extractDescription(lines);
      const body = lines.filter((_, index) => index !== titleInfo?.index).join('\n');
      const route = routeSegments(item, locale).join('/');

      records.push({
        url: `/${route}/`,
        language,
        meta: { title, description },
        content: [title, description, markdownToText(body)].filter(Boolean).join('\n\n'),
      });
    }
  }
  return records;
}

/**
 * Build the index in a temporary directory and swap it into place, so a rebuild never serves a
 * half-written index. Pagefind's service is closed afterwards; the next call restarts it.
 */
export async function buildDevSearchIndex(
  outputPath,
  { records = collectDevSearchRecords() } = {},
) {
  const tempPath = `${outputPath}.tmp-${process.pid}-${Date.now()}`;
  rmSync(tempPath, { recursive: true, force: true });
  mkdirSync(tempPath, { recursive: true });

  const { index, errors } = await pagefind.createIndex();
  if (!index) {
    rmSync(tempPath, { recursive: true, force: true });
    await pagefind.close();
    throw new Error(`Pagefind could not create an index: ${errors.join('; ')}`);
  }

  try {
    for (const record of records) {
      const result = await index.addCustomRecord(record);
      if (result.errors.length > 0) {
        throw new Error(`Pagefind could not index ${record.url}: ${result.errors.join('; ')}`);
      }
    }
    const written = await index.writeFiles({ outputPath: tempPath });
    if (written.errors.length > 0) {
      throw new Error(`Pagefind could not write the index: ${written.errors.join('; ')}`);
    }
    rmSync(outputPath, { recursive: true, force: true });
    renameSync(tempPath, outputPath);
  } catch (error) {
    rmSync(tempPath, { recursive: true, force: true });
    throw error;
  } finally {
    await pagefind.close();
  }

  return { pages: records.length, outputPath };
}
